===bench_n.sh===
#!/usr/bin/env bash
# Isolated per-N benchmark: run eval.py benchmark over ONLY the shapes whose n
# matches $2 (e.g. 1024), report their geomean us. $1=<set>/<problem>. Lets a
# tile/precision knob be swept on one shape regime fast (3 n=1024 shapes) instead
# of all 12. Honours QR_* env knobs (exported by the caller). Prints geomean_us.
set -uo pipefail
HARNESS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/harness" && pwd)"
source "$HARNESS_DIR/env.sh" "$1"
NWANT="$2"
# Build a spec file with only the matching-n benchmark shapes.
ALL="$("$PYTHON" "$REPO_DIR/bin/gen_specs.py" "$PROBLEM_DIR/task.yml" --emit benchmarks)"
SPECFILE="$(mktemp)"; OUT="$(mktemp)"; trap 'rm -f "$SPECFILE" "$OUT"' EXIT
echo "$ALL" | grep -E "n: ${NWANT};" > "$SPECFILE"
NSHAPES=$(wc -l < "$SPECFILE")
cd "$PROBLEM_DIR" || exit 1
POPCORN_FD=3 "$PYTHON" "$EVAL_PY" benchmark "$SPECFILE" 3>"$OUT"
rc=$?
[ $rc -eq 0 ] || { echo "FAILED rc=$rc" >&2; cat "$OUT" >&2; exit $rc; }
"$PYTHON" - "$OUT" "$NSHAPES" <<'PY'
import sys,re,math
out=open(sys.argv[1]).read().splitlines()
means={}
for ln in out:
    m=re.match(r"benchmark\.(\d+)\.mean:\s*([0-9.eE+-]+)",ln)
    if m: means[int(m.group(1))]=float(m.group(2))
    m=re.match(r"benchmark\.(\d+)\.spec:\s*(.+)",ln)
if not means:
    print("NO MEANS",file=sys.stderr); sys.exit(1)
vals=[means[k] for k in sorted(means)]
g=math.exp(sum(math.log(v) for v in vals)/len(vals))
print(f"n{sys.argv[2]}_geomean_us={g/1000:.3f}  shapes={len(vals)}  per_shape_us={[round(v/1000,1) for v in vals]}")
PY
