#!/usr/bin/env bash
# Per-shape nsys profiling driver. Sets up the qr_v2 env (like benchmark.sh) and
# runs eval.py benchmark on a SINGLE shape spec passed as $2, so nsys (wrapping
# THIS script) captures only that shape's kernel timeline. $1 = <set>/<problem>.
# $2 = a single benchmark spec line (e.g. "batch: 640; n: 512; cond: 2; seed: 1029").
set -uo pipefail
HARNESS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/harness" && pwd)"
source "$HARNESS_DIR/env.sh" "$1"
SPEC="$2"
SPECFILE="$(mktemp)"; trap 'rm -f "$SPECFILE"' EXIT
printf '%s\n' "$SPEC" > "$SPECFILE"
cd "$PROBLEM_DIR" || exit 1
POPCORN_FD=3 "$PYTHON" "$EVAL_PY" benchmark "$SPECFILE" 3>/dev/null
